#!/usr/bin/env python3
"""Cross-index: for each (file, lockexpr) with a plain handler acquisition, find
other plain spin_lock acquisitions of the same lock expression in the same file
OUTSIDE the handler body (potential non-irq context)."""
import re, os
from collections import defaultdict

ROOT = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/10_cluster/C7/public/snapshots/s04"
T = os.environ.get("TMPDIR", "/tmp") + "/i047"

lock_re = re.compile(r"spin_lock(?:_irqsave|_irq|_bh)?\s*\(\s*(?:&\s*)?([^,\)\s]+)\s*")

plain_pairs = defaultdict(set)   # (file, lockexpr) -> {regline}
handler_plain = defaultdict(list)  # (file, lockexpr) -> [(handler, regline, lockline)]

with open(T + "/handler_locks.tsv") as f:
    for line in f:
        parts = line.rstrip("\n").split("\t")
        if len(parts) != 7:
            continue
        path, regline, h, kind, lockexpr, mode, lockline = parts
        if mode == "plain":
            handler_plain[(path, lockexpr)].append((h, int(regline), int(lockline)))

out = []
for (path, lockexpr), hlist in handler_plain.items():
    try:
        with open(os.path.join(ROOT, path), errors="replace") as f:
            lines = f.readlines()
    except OSError:
        continue
    other_plain = []   # (lineno, line-content)
    other_safe = 0
    for i, l in enumerate(lines):
        m = lock_re.search(l)
        if not m:
            continue
        le = m.group(1)
        if le != lockexpr:
            continue
        # determine mode
        if m.group(0).startswith("spin_lock("):
            mode = "plain"
        elif m.group(0).startswith("spin_lock_irqsave"):
            mode = "irqsave"
        elif m.group(0).startswith("spin_lock_irq"):
            mode = "irq"
        elif m.group(0).startswith("spin_lock_bh"):
            mode = "bh"
        else:
            mode = "?"
        if mode != "plain":
            other_safe += 1
            continue
        # is this line inside one of the handler bodies?
        lineno = i + 1
        inhandler = False
        for (h, regline, lockline) in hlist:
            if abs(lineno - lockline) < 3:
                inhandler = True
        if not inhandler:
            other_plain.append((lineno, l.strip()))
    if other_plain:
        out.append((path, lockexpr, hlist, other_plain, other_safe))

out.sort(key=lambda x: -len(x[3]))
with open(T + "/cross.tsv", "w") as f:
    for path, lockexpr, hlist, other_plain, other_safe in out:
        f.write(f"{path}\t{lockexpr}\thandler_plain={len(hlist)}\tother_plain={len(other_plain)}\tother_safe={other_safe}\n")
        for (h, regline, lockline) in hlist[:3]:
            f.write(f"  HANDLER {h} reg={regline} lockline={lockline}\n")
        for (lineno, content) in other_plain[:6]:
            f.write(f"  OTHER {lineno}: {content}\n")
print("candidate (file, lock) pairs with plain handler AND plain elsewhere:", len(out))
print()
with open(T + "/cross.tsv") as f:
    print(f.read()[:6000])
